package com.luminor.tavernquest.feature.quest.detail
import androidx.lifecycle.*;import com.luminor.tavernquest.domain.model.ContractStatus;import com.luminor.tavernquest.domain.usecase.contract.AcceptContractUseCase;import com.luminor.tavernquest.domain.usecase.quest.GetQuestUseCase;import dagger.hilt.android.lifecycle.HiltViewModel;import javax.inject.Inject;import kotlinx.coroutines.flow.*;import kotlinx.coroutines.launch
@HiltViewModel class QuestDetailViewModel @Inject constructor(saved:SavedStateHandle,private val get:GetQuestUseCase,private val acceptUse:AcceptContractUseCase):ViewModel(){private val id:String=saved["id"]?:"";private val _ui=MutableStateFlow(QuestDetailUiState());val ui=_ui.asStateFlow();init{viewModelScope.launch{_ui.value=QuestDetailUiState(get(id),false)}};fun accept(){viewModelScope.launch{if(acceptUse(id)){_ui.update{it.copy(quest=it.quest?.copy(status=ContractStatus.ACCEPTED),accepted=true)}}else _ui.update{it.copy(message="Não foi possível aceitar este contrato.")}}}}
